function startScene4() {
  const iacPage   = _root.getElementById('iacPage');
  const compPage  = _root.getElementById('comparisonPage');
  const chatPanel = _root.querySelector('.chat-panel');
  const tabs      = _root.querySelectorAll('.topnav-tabs .tab');

  // Fade out comparison + sidebar
  compPage.style.transition = 'opacity 0.3s ease';
  compPage.style.opacity = '0';
  chatPanel.style.transition = 'opacity 0.3s ease';
  chatPanel.style.opacity = '0';

  setTimeout(() => {
    compPage.classList.remove('visible');
    compPage.style.transition = '';
    compPage.style.opacity = '';
    chatPanel.style.display = 'none';

    tabs.forEach(t => t.classList.remove('active'));
    tabs[1].classList.add('active');

    iacPage.classList.add('visible');
    streamTerraformLines();
  }, 320);
}

function streamTerraformLines() {
  const codeEl   = _root.getElementById('iacCode');
  const gutterEl = _root.getElementById('iacGutter');
  codeEl.innerHTML = '';
  gutterEl.innerHTML = '';

  const INTERVAL = 19;
  let i = 0;
  let lineNum = 1;

  function addLine() {
    if (i >= TF_LINES.length) {
      const statusEl = _root.getElementById('iacStatus');
      statusEl.classList.add('done');
      statusEl.querySelector('.iac-status-label').textContent = 'Complete';
      // Pause briefly then transition to deploy scene
      setTimeout(() => startScene5(), 900);
      return;
    }
    const entry = TF_LINES[i++];
    const line = document.createElement('span');
    line.className = 'iac-line';
    line.innerHTML = entry.t || '&nbsp;';
    codeEl.appendChild(line);

    const gLine = document.createElement('span');
    gLine.className = 'iac-gutter-line';
    gLine.textContent = entry.t ? lineNum++ : '';
    gutterEl.appendChild(gLine);

    codeEl.scrollTop = codeEl.scrollHeight;
    gutterEl.scrollTop = gutterEl.scrollHeight;

    setTimeout(addLine, INTERVAL);
  }
  addLine();
}

function _showScene4() {
  const iacPage     = _root.getElementById('iacPage');
  const compPage    = _root.getElementById('comparisonPage');
  const chatPanel   = _root.querySelector('.chat-panel');
  const tabs        = _root.querySelectorAll('.topnav-tabs .tab');
  const mainEl      = _root.querySelector('main.main');
  const clioFocused = _root.querySelector('.clio-focused');
  const blurOverlay = _root.querySelector('.blur-overlay');

  mainEl.style.display = 'none';
  compPage.classList.remove('visible');
  chatPanel.style.display = 'none';
  chatPanel.style.opacity = '';
  clioFocused.style.cssText = 'opacity:0; animation:none; display:none;';
  blurOverlay.style.cssText = 'opacity:0; animation:none; display:none;';
  tabs.forEach(t => t.classList.remove('active'));
  tabs[1].classList.add('active');

  iacPage.classList.add('visible');
  const codeEl   = _root.getElementById('iacCode');
  const gutterEl = _root.getElementById('iacGutter');
  codeEl.innerHTML = '';
  gutterEl.innerHTML = '';
  let lineNum = 1;
  TF_LINES.forEach(entry => {
    const line = document.createElement('span');
    line.className = 'iac-line';
    line.style.animationDuration = '0s';
    line.innerHTML = entry.t || '&nbsp;';
    codeEl.appendChild(line);
    const gLine = document.createElement('span');
    gLine.className = 'iac-gutter-line';
    gLine.textContent = entry.t ? lineNum++ : '';
    gutterEl.appendChild(gLine);
  });
  const statusEl = _root.getElementById('iacStatus');
  statusEl.classList.add('done');
  statusEl.querySelector('.iac-status-label').textContent = 'Complete';
}

