// ── Checkpoint definitions ────────────────────────────────────────────────────
// Each checkpoint has a time (ms from start) and a restore() that sets the DOM
// to exactly that state (no animations, instant).

function _killAllAnimations() {
  // Cancel every tracked setTimeout/setInterval
  _timerIds.forEach(id => { _nativeClearTimeout(id); _nativeClearInterval(id); });
  _timerIds.clear();
  _animStart = Date.now() - TOTAL_DURATION - 1000;
}

